//! `libgojni.so`: native side of the gobind-generated firestack Java facade.
//!
//! Java (vendored verbatim from `com.celzero:firestack:<sha>:sources`, see `engine/android/facade`) declares
//! 1000+ `native` methods. `exports.rs` (generated by `tools/jni-gen` from `engine/api/natives.tsv`) exports one
//! `Java_…` symbol per native. Each one either dispatches to a real implementation in [`impls`], to the generic
//! struct store / Seq runtime in [`rt`], or to a stub that throws `unimplemented` (for `throws Exception`
//! methods) or returns Go's zero value.

#![allow(clippy::missing_safety_doc)]

#[rustfmt::skip]
mod exports;
pub mod cbexec;
pub mod impls;
pub mod rt;

pub use exports::{
    FIRESTACK_PIN, NATIVE_COUNT, NATIVE_SYMBOLS, PROXY_CLASSES, STUB_CENSUS, implemented_count,
};
